            List<AggregateResult> results = [
                SELECT SUM(Amount) aggregateAmount
                FROM Opportunity
                WHERE StageName = :stage
                  AND CloseDate >= :fromDate
                  AND CloseDate <= :toDate
            ];

            if (!results.isEmpty()) {
                Object sumValue = results[0].get('aggregateAmount');
                if (sumValue != null) {
                    total = (Decimal) sumValue;
                }
            }

            totals.put(stage, total);
        }

