        if (!this._options || this._options.length === 0) {
            this.activeOptionIndex = 0;
            return;
        }

        const selectedIndex = this._options.findIndex(
            (option) => option.value === this._value
        );

        this.activeOptionIndex = selectedIndex >= 0 ? selectedIndex : 0;
    }

    get activeOptionId() {
        if (!this._options || this._options.length === 0) {
            return null;
        }

        return `statusListbox-option-${this.activeOptionIndex}`;
    }

    get optionItems() {
        if (!this._options || this._options.length === 0) {
            return [];
        }

        return this._options.map((option, index) => {
            const isSelected = option.value === this._value;
            const optionId = `statusListbox-option-${index}`;

            return {
                ...option,
                optionId,
                isSelected,
                className: isSelected ? 'selected' : '',
                ariaSelected: isSelected ? 'true' : 'false',
            };
        });
    }

    handleKeyDown(event) {
        const key = event.key;
        const maxIndex = this._options.length - 1;

        if (key === 'ArrowDown') {
            event.preventDefault();
            this.activeOptionIndex = Math.min(this.activeOptionIndex + 1, maxIndex);
        } else if (key === 'ArrowUp') {
            event.preventDefault();
            this.activeOptionIndex = Math.max(this.activeOptionIndex - 1, 0);
        } else if (key === 'Home') {
            event.preventDefault();
            this.activeOptionIndex = 0;
        } else if (key === 'End') {
            event.preventDefault();
            this.activeOptionIndex = maxIndex;
        } else if (key === 'Enter' || key === ' ') {
            event.preventDefault();
            this.selectActiveOption();
        }
    }

    selectActiveOption() {
        const activeElement = this.template.querySelector(
            `[id="${this.activeOptionId}"]`
        );

        if (!activeElement) {
            return;
        }

        const newValue = activeElement.dataset.value;

        if (newValue === this._value) {
            return;
        }

        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: newValue },
                bubbles: true,
                composed: true,
            })
        );
    }

    handleOptionClick(event) {
        const clickedOption = event.currentTarget;
        const clickedIndex = parseInt(clickedOption.getAttribute('data-index'), 10);
        const newValue = clickedOption.dataset.value;

        if (newValue === this._value) {
            // Even if already selected, if it's a different active option, update the active option
            this.activeOptionIndex = clickedIndex;
            return;
        }

        // Update the active option to the clicked option
        this.activeOptionIndex = clickedIndex;

        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: newValue },
                bubbles: true,
                composed: true,
            })
        );
    }
}
