public class EmployerService {
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // Remove any entries where the employer is null or the same as the contact Id
        Map<Id, Id> contactIdToEmployerId = new Map<Id, Id>();
        for (Id contactId : employerByContactId.keySet()) {
            Id employerId = employerByContactId.get(contactId);
            if (employerId != null && employerId != contactId) {
                contactIdToEmployerId.put(contactId, employerId);
            }
        }

        if (contactIdToEmployerId.isEmpty()) {
            return;
        }

        // Query existing primary affiliations for the contacts
        List<npe5__Affiliation__c> existingAffiliations = [
            SELECT Id, npe5__Contact__c, npe5__Organization__c, npe5__Primary__c, npe5__Status__c,
                   npe5__StartDate__c, npe5__EndDate__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :contactIdToEmployerId.keySet()
              AND npe5__Primary__c = true
        ];

        // Group affiliations by contact Id to handle multiple affiliations per contact
        Map<Id, List<npe5__Affiliation__c>> affiliationsByContact = new Map<Id, List<npe5__Affiliation__c>>();
        for (npe5__Affiliation__c affiliation : existingAffiliations) {
            if (!affiliationsByContact.containsKey(affiliation.npe5__Contact__c)) {
                affiliationsByContact.put(affiliation.npe5__Contact__c, new List<npe5__Affiliation__c>());
            }
            affiliationsByContact.get(affiliation.npe5__Contact__c).add(affiliation);
        }

        Map<Id, Id> existingPrimaryEmployerByContact = new Map<Id, Id>();
        for (Id contactId : affiliationsByContact.keySet()) {
            List<npe5__Affiliation__c> contactAffiliations = affiliationsByContact.get(contactId);
            for (npe5__Affiliation__c affiliation : contactAffiliations) {
                if (affiliation.npe5__Primary__c) {
                    existingPrimaryEmployerByContact.put(contactId, affiliation.npe5__Organization__c);
                    break;
                }
            }
        }

        List<npe5__Affiliation__c> affiliationsToArchive = new List<npe5__Affiliation__c>();
        List<npe5__Affiliation__c> affiliationsToCreate = new List<npe5__Affiliation__c>();
        Set<Id> contactsToUpdate = new Set<Id>();

        for (Id contactId : contactIdToEmployerId.keySet()) {
            Id newEmployerId = contactIdToEmployerId.get(contactId);
            Id existingEmployerId = existingPrimaryEmployerByContact.get(contactId);

            if (existingEmployerId == null) {
                // No existing primary affiliation - create new one
                npe5__Affiliation__c newAffiliation = new npe5__Affiliation__c(
                    npe5__Contact__c = contactId,
                    npe5__Organization__c = newEmployerId,
                    npe5__Primary__c = true,
                    npe5__Status__c = 'Current',
                    npe5__StartDate__c = Date.today()
                );
                affiliationsToCreate.add(newAffiliation);
                contactsToUpdate.add(contactId);
            } else if (existingEmployerId != newEmployerId) {
                // Different employer - archive old ones and create new one
                List<npe5__Affiliation__c> contactAffiliations = affiliationsByContact.get(contactId);
                for (npe5__Affiliation__c affiliation : contactAffiliations) {
                    affiliation.npe5__Primary__c = false;
                    affiliation.npe5__Status__c = 'Former';
                    affiliation.npe5__EndDate__c = Date.today();
                    affiliationsToArchive.add(affiliation);
                }

                npe5__Affiliation__c newAffiliation = new npe5__Affiliation__c(
                    npe5__Contact__c = contactId,
                    npe5__Organization__c = newEmployerId,
                    npe5__Primary__c = true,
                    npe5__Status__c = 'Current',
                    npe5__StartDate__c = Date.today()
                );
                affiliationsToCreate.add(newAffiliation);
                contactsToUpdate.add(contactId);
            }
            // If existingEmployerId == newEmployerId, do nothing (no changes)
